        tree: "\u3010\u4EC5\u8BB0\u5F55\u529F\u80FD\u3011",
        cult: "\u53E4\u7C4D\u4FEE\u8EAB\u4E66\u5355",
        cog: "\u4E94\u7EF4\u6A21\u578B\u5468\u671F",
