      { id: "edge-" + c2 + "-" + c3, sourceId: c2, targetId: c3, sourceLabel: "\u653B\u575A\u5B9E\u8BAD", targetLabel: "\u8BC4\u4F30\u590D\u76D8", label: "\u590D\u76D8\u7EA0\u504F", type: "\u5173\u8054", arrowMode: "single", lineStyle: "dashed", lineWidth: 3, color: "#10b981" }
