    showIslandToast("\u{1F50D} \u805A\u7126\u6A21\u5F0F\uFF1A\u5DF2\u5C06\u89C6\u53E3\u955C\u5934\u9501\u5B9A\u81F3\u5F53\u524D\u6838\u5FC3\u653B\u575A\u5E8F\u5217");
