    showIslandToast("\u{1F512} \u8282\u70B9\u9501\u5B9A\u72B6\u6001\u5DF2\u5207\u6362\uFF1A\u753B\u5E03\u5F53\u524D\u5361\u7247\u5DF2\u5C31\u4F4D");
